14	@Component({
15	  selector: 'app-product-list',
16	  imports: [CurrencyPipe, CategoryNav],
17	  templateUrl: './product-list.html',
18	  styleUrl: './product-list.scss'
19	})
20	export class ProductList implements OnInit {
21	  private readonly productService = inject(ProductService);
22	
23	  readonly page = signal(1);
24	  readonly result = signal<PagedResult<ProductListItem> | null>(null);
25	  readonly error = signal(false);
26	  readonly categoryId = signal<string | null>(null);
27	  readonly subcategoryId = signal<string | null>(null);
28	  readonly sortBy = signal<ProductSortBy>('name');
29	  readonly sortDirection = signal<ProductSortDirection>('asc');
30	  readonly search = signal('');
31	  private readonly submittedSearch = signal('');
32	  readonly attributeFilterSelections = signal<Record<string, string>>({});
33	
34	  private latestRequestId = 0;
35	
36	  ngOnInit(): void {
37	    this.loadPage(1);
38	  }
39	
40	  onCategorySelectionChange(selection: CategorySelection): void {
41	    this.attributeFilterSelections.set({});
42	    this.categoryId.set(selection.categoryId);
43	    this.subcategoryId.set(selection.subcategoryId);
44	    this.loadPage(1);
45	  }
46	
47	  onAttributeFilterChange(name: string, event: Event): void {
48	    const value = (event.target as HTMLSelectElement).value;
49	    const current = { ...this.attributeFilterSelections() };
50	    if (value) {
51	      current[name] = value;
52	    } else {
53	      delete current[name];
54	    }
55	    this.attributeFilterSelections.set(current);
56	    this.loadPage(1);
57	  }
58	
59	  onSortByChange(event: Event): void {
60	    this.sortBy.set((event.target as HTMLSelectElement).value as ProductSortBy);
61	    this.loadPage(1);
62	  }
63	
64	  onSortDirectionChange(event: Event): void {
65	    this.sortDirection.set((event.target as HTMLSelectElement).value as ProductSortDirection);
66	    this.loadPage(1);
67	  }
68	
69	  onSearchSubmit(): void {
70	    this.submittedSearch.set(this.search());
71	    this.loadPage(1);
72	  }
73	
74	  onSearchInputChange(event: Event): void {
75	    this.search.set((event.target as HTMLInputElement).value);
