7	public static class DatabaseInitializer
8	{
9	    private static readonly JsonSerializerOptions SerializerOptions = new()
10	    {
11	        PropertyNameCaseInsensitive = true
12	    };
13	
14	    public static async Task MigrateAsync(AppDbContext db)
15	    {
16	        await db.Database.MigrateAsync();
17	    }
18	
19	    public static async Task SeedIfEmptyAsync(AppDbContext db, string seedFilePath)
20	    {
21	        if (await db.Products.AnyAsync())
22	        {
23	            return;
24	        }
25	
26	        await using var stream = File.OpenRead(seedFilePath);
27	        var seed = await JsonSerializer.DeserializeAsync<SeedRoot>(stream, SerializerOptions)
28	            ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{seedFilePath}' gelesen werden.");
29	
30	        foreach (var kategorie in seed.Kategorien)
31	        {
32	            db.Categories.Add(new Category { Id = kategorie.Id, Name = kategorie.Name });
33	
34	            foreach (var unterkategorie in kategorie.Unterkategorien)
35	            {
36	                db.Subcategories.Add(new Subcategory
37	                {
38	                    Id = unterkategorie.Id,
39	                    Name = unterkategorie.Name,
40	                    CategoryId = kategorie.Id,
41	                    AttributeNames = unterkategorie.Eigenschaften
42	                });
43	            }
44	        }
45	
46	        foreach (var lieferant in seed.Lieferanten)
47	        {
48	            db.Suppliers.Add(new Supplier { Id = lieferant.Id, Name = lieferant.Name });
49	        }
50	
51	        foreach (var produkt in seed.Produkte)
52	        {
53	            db.Products.Add(new Product
54	            {
55	                Id = produkt.Id,
56	                Name = produkt.Name,
57	                Description = produkt.Beschreibung,
58	                SubcategoryId = produkt.UnterkategorieId,
59	                Attributes = produkt.Eigenschaften.GetRawText(),
60	                ViewCount = 0
61	            });
62	
63	            foreach (var angebot in produkt.Angebote)
64	            {
65	                db.Offers.Add(new Offer
66	                {
67	                    ProductId = produkt.Id,
68	                    SupplierId = angebot.LieferantId,
69	                    Price = angebot.Preis
70	                });
71	            }
72	        }
73	
74	        await db.SaveChangesAsync();
75	    }
