13	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(int page, string? categoryId = null, string? subcategoryId = null, string? sortBy = null, string? sortDirection = null, string? search = null, string[]? attr = null)
14	    {
15	        page = page < 1 ? 1 : page;
16	
17	        IQueryable<Product> query = db.Products.Include(p => p.Subcategory);
18	
19	        if (!string.IsNullOrEmpty(subcategoryId))
20	        {
21	            query = query.Where(p => p.SubcategoryId == subcategoryId);
22	        }
23	        else if (!string.IsNullOrEmpty(categoryId))
24	        {
25	            query = query.Where(p => p.Subcategory!.CategoryId == categoryId);
26	        }
27	
28	        if (!string.IsNullOrWhiteSpace(search))
29	        {
30	            var loweredSearch = search.Trim().ToLower();
31	            query = query.Where(p => p.Name.ToLower().Contains(loweredSearch) || p.Description.ToLower().Contains(loweredSearch));
32	        }
33	
34	        var attributeFilters = ParseAttributeFilters(attr);
35	        if (attributeFilters.Count > 0)
36	        {
37	            var candidates = await query.Select(p => new { p.Id, p.Attributes }).ToListAsync();
38	            var matchingIds = candidates
39	                .Where(c => attributeFilters.All(f => ProductAttributeJson.Matches(c.Attributes, f.Name, f.Value)))
40	                .Select(c => c.Id)
41	                .ToList();
42	            query = query.Where(p => matchingIds.Contains(p.Id));
43	        }
44	
45	        var availableAttributeFilters = string.IsNullOrEmpty(subcategoryId)
46	            ? (IReadOnlyList<AttributeFilterOptionDto>)Array.Empty<AttributeFilterOptionDto>()
47	            : await BuildAvailableAttributeFiltersAsync(subcategoryId);
48	
49	        var totalCount = await query.CountAsync();
50	
51	        // long arithmetic + clamp to totalCount avoids an int overflow into a negative
52	        // Skip() for very large page values while preserving "beyond last page -> empty" behavior.
53	        var skip = (int)Math.Min((long)(page - 1) * PageSize, totalCount);
54	
55	        var descending = sortDirection == "desc";
56	        IOrderedQueryable<Product> orderedQuery = sortBy switch
57	        {
58	            "price" => descending
59	                ? query.OrderByDescending(p => p.Offers.Min(o => o.Price))
60	                : query.OrderBy(p => p.Offers.Min(o => o.Price)),
61	            "views" => query.OrderByDescending(p => p.ViewCount),
62	            _ => descending
63	                ? query.OrderByDescending(p => p.Name.ToLower())
64	                : query.OrderBy(p => p.Name.ToLower())
65	        };
66	
67	        var items = await orderedQuery
68	            .ThenBy(p => p.Id)
69	            .Skip(skip)
70	            .Take(PageSize)
71	            .Select(p => new ProductListItemDto(
72	                p.Id,
73	                p.Name,
74	                p.Subcategory!.Name,
75	                p.Offers.Min(o => o.Price)))
76	            .ToListAsync();
77	
78	        var totalPages = (int)Math.Ceiling(totalCount / (double)PageSize);
79	
80	        return new PagedResultDto<ProductListItemDto>(items, page, PageSize, totalCount, totalPages, availableAttributeFilters);
81	    }
