83	    private static List<(string Name, string Value)> ParseAttributeFilters(string[]? attr)
84	    {
85	        if (attr is null) { return []; }
86	
87	        var result = new List<(string Name, string Value)>();
88	        foreach (var entry in attr)
89	        {
90	            var separatorIndex = entry.IndexOf(':');
91	            if (separatorIndex <= 0 || separatorIndex == entry.Length - 1) { continue; }
92	            result.Add((entry[..separatorIndex], entry[(separatorIndex + 1)..]));
93	        }
94	        return result;
95	    }
