97	    private async Task<IReadOnlyList<AttributeFilterOptionDto>> BuildAvailableAttributeFiltersAsync(string subcategoryId)
98	    {
99	        var attributeNames = await db.Subcategories
100	            .Where(s => s.Id == subcategoryId)
101	            .Select(s => s.AttributeNames)
102	            .FirstOrDefaultAsync();
103	
104	        if (attributeNames is null || attributeNames.Count == 0)
105	        {
106	            return Array.Empty<AttributeFilterOptionDto>();
107	        }
108	
109	        var attributesJsonList = await db.Products
110	            .Where(p => p.SubcategoryId == subcategoryId)
111	            .Select(p => p.Attributes)
112	            .ToListAsync();
113	
114	        var result = new List<AttributeFilterOptionDto>();
115	        foreach (var name in attributeNames)
116	        {
117	            var distinctValues = attributesJsonList
118	                .Select(json => ProductAttributeJson.TryFormatValue(json, name))
119	                .Where(v => v is not null)
120	                .Select(v => v!)
121	                .Distinct()
122	                .ToList();
123	
124	            // Numeric attributes (e.g. LeistungWatt) must sort by value, not lexically ("1800" < "300"
125	            // under ordinal text comparison) — only falls back to ordinal text order for non-numeric attributes.
126	            var values = distinctValues.All(v => decimal.TryParse(v, NumberStyles.Number, CultureInfo.InvariantCulture, out _))
127	                ? distinctValues.OrderBy(v => decimal.Parse(v, NumberStyles.Number, CultureInfo.InvariantCulture)).ToList()
128	                : distinctValues.OrderBy(v => v, StringComparer.Ordinal).ToList();
129	            result.Add(new AttributeFilterOptionDto(name, values));
130	        }
131	        return result;
132	    }
